contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable {
        require(amount <= address(c).balance, "insufficient balance");

        uint beforeBalance = address(c).balance;
        c.withdraw(amount); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        assert(afterBalance + amount == beforeBalance);
    }

    receive() external payable {}
}

